/*
 * `app calc`: evaluate one 64-bit signed integer expression per input line.
 *
 * The parser is an operator-precedence (shunting-yard) evaluator driven by
 * explicit, growable stacks rather than recursion, so arbitrarily deep
 * nesting such as "((((...))))" or "-----1" cannot exhaust the C stack.
 * Values are reduced eagerly as operators are popped, and every arithmetic
 * step is checked for overflow without invoking undefined behaviour.
 */
#include "calc.h"

#include <inttypes.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

enum op {
    OP_LPAREN,
    OP_ADD,
    OP_SUB,
    OP_MUL,
    OP_DIV,
    OP_MOD,
    OP_NEG,
};

enum status {
    ST_OK,      /* *out holds the value */
    ST_BLANK,   /* line is empty or whitespace only: print nothing */
    ST_ERROR,   /* syntax, division by zero, or overflow */
    ST_NOMEM,   /* allocation failure */
};

struct evaluator {
    int64_t *vals;
    size_t nvals, capvals;
    unsigned char *ops;
    size_t nops, capops;
};

static int precedence(enum op op)
{
    switch (op) {
    case OP_ADD:
    case OP_SUB:
        return 1;
    case OP_MUL:
    case OP_DIV:
    case OP_MOD:
        return 2;
    case OP_NEG:
        return 3;
    case OP_LPAREN:
        break;
    }
    return 0;
}

/* Ensure room for one more element in a stack; returns false on ENOMEM. */
static bool reserve(void **base, size_t *cap, size_t len, size_t elem)
{
    if (len < *cap)
        return true;
    size_t ncap = *cap ? *cap * 2 : 64;
    if (ncap > SIZE_MAX / elem)
        return false;
    void *p = realloc(*base, ncap * elem);
    if (!p)
        return false;
    *base = p;
    *cap = ncap;
    return true;
}

static bool push_val(struct evaluator *ev, int64_t v)
{
    void *base = ev->vals;
    if (!reserve(&base, &ev->capvals, ev->nvals, sizeof *ev->vals))
        return false;
    ev->vals = base;
    ev->vals[ev->nvals++] = v;
    return true;
}

static bool push_op(struct evaluator *ev, enum op op)
{
    void *base = ev->ops;
    if (!reserve(&base, &ev->capops, ev->nops, sizeof *ev->ops))
        return false;
    ev->ops = base;
    ev->ops[ev->nops++] = (unsigned char)op;
    return true;
}

/* Checked arithmetic: each returns false if the exact result is out of range. */
static bool checked_add(int64_t a, int64_t b, int64_t *r)
{
    if ((b > 0 && a > INT64_MAX - b) || (b < 0 && a < INT64_MIN - b))
        return false;
    *r = a + b;
    return true;
}

static bool checked_sub(int64_t a, int64_t b, int64_t *r)
{
    if ((b < 0 && a > INT64_MAX + b) || (b > 0 && a < INT64_MIN + b))
        return false;
    *r = a - b;
    return true;
}

static bool checked_mul(int64_t a, int64_t b, int64_t *r)
{
    if (a > 0) {
        if (b > 0 ? a > INT64_MAX / b : b < INT64_MIN / a)
            return false;
    } else if (a < 0) {
        if (b > 0 ? a < INT64_MIN / b : (b < 0 && a < INT64_MAX / b))
            return false;
    }
    *r = a * b;
    return true;
}

static bool checked_div(int64_t a, int64_t b, int64_t *r)
{
    if (b == 0 || (a == INT64_MIN && b == -1))
        return false;
    *r = a / b;
    return true;
}

static bool checked_mod(int64_t a, int64_t b, int64_t *r)
{
    if (b == 0)
        return false;
    /* INT64_MIN % -1 is mathematically 0 but undefined behaviour in C. */
    *r = b == -1 ? 0 : a % b;
    return true;
}

/* Pop the top operator (never a parenthesis) and reduce its operands. */
static bool apply_top(struct evaluator *ev)
{
    enum op op = (enum op)ev->ops[--ev->nops];

    if (op == OP_NEG) {
        int64_t *a = &ev->vals[ev->nvals - 1];
        if (*a == INT64_MIN)
            return false;
        *a = -*a;
        return true;
    }

    int64_t b = ev->vals[--ev->nvals];
    int64_t *a = &ev->vals[ev->nvals - 1];
    switch (op) {
    case OP_ADD: return checked_add(*a, b, a);
    case OP_SUB: return checked_sub(*a, b, a);
    case OP_MUL: return checked_mul(*a, b, a);
    case OP_DIV: return checked_div(*a, b, a);
    case OP_MOD: return checked_mod(*a, b, a);
    case OP_NEG:
    case OP_LPAREN:
        break;
    }
    return false;
}

static bool is_blank(char c)
{
    return c == ' ' || c == '\t';
}

static bool is_digit(char c)
{
    return c >= '0' && c <= '9';
}

static enum status evaluate(struct evaluator *ev, const char *s, size_t len,
                            int64_t *out)
{
    size_t i = 0;
    bool expect_operand = true;
    bool any_token = false;

    ev->nvals = 0;
    ev->nops = 0;

    for (;;) {
        while (i < len && is_blank(s[i]))
            i++;
        if (i == len)
            break;
        any_token = true;
        char c = s[i++];

        if (expect_operand) {
            if (is_digit(c)) {
                int64_t v = c - '0';
                while (i < len && is_digit(s[i])) {
                    int d = s[i++] - '0';
                    if (v > (INT64_MAX - d) / 10)
                        return ST_ERROR;
                    v = v * 10 + d;
                }
                if (!push_val(ev, v))
                    return ST_NOMEM;
                expect_operand = false;
            } else if (c == '-') {
                if (!push_op(ev, OP_NEG))
                    return ST_NOMEM;
            } else if (c == '(') {
                if (!push_op(ev, OP_LPAREN))
                    return ST_NOMEM;
            } else {
                return ST_ERROR;
            }
            continue;
        }

        enum op op;
        switch (c) {
        case '+': op = OP_ADD; break;
        case '-': op = OP_SUB; break;
        case '*': op = OP_MUL; break;
        case '/': op = OP_DIV; break;
        case '%': op = OP_MOD; break;
        case ')':
            while (ev->nops > 0 && ev->ops[ev->nops - 1] != OP_LPAREN) {
                if (!apply_top(ev))
                    return ST_ERROR;
            }
            if (ev->nops == 0)
                return ST_ERROR;    /* unmatched ')' */
            ev->nops--;
            continue;
        default:
            return ST_ERROR;
        }

        /* All binary operators are left-associative. */
        int prec = precedence(op);
        while (ev->nops > 0 && ev->ops[ev->nops - 1] != OP_LPAREN &&
               precedence((enum op)ev->ops[ev->nops - 1]) >= prec) {
            if (!apply_top(ev))
                return ST_ERROR;
        }
        if (!push_op(ev, op))
            return ST_NOMEM;
        expect_operand = true;
    }

    if (!any_token)
        return ST_BLANK;
    if (expect_operand)
        return ST_ERROR;            /* missing operand */

    while (ev->nops > 0) {
        if (ev->ops[ev->nops - 1] == OP_LPAREN)
            return ST_ERROR;        /* unmatched '(' */
        if (!apply_top(ev))
            return ST_ERROR;
    }
    *out = ev->vals[0];
    return ST_OK;
}

/* Evaluate one line and print its result; returns false on ENOMEM. */
static bool process_line(struct evaluator *ev, const char *s, size_t len)
{
    int64_t value;

    switch (evaluate(ev, s, len, &value)) {
    case ST_OK:
        printf("%" PRId64 "\n", value);
        break;
    case ST_ERROR:
        fputs("error\n", stdout);
        break;
    case ST_BLANK:
        break;
    case ST_NOMEM:
        return false;
    }
    return true;
}

/* Append bytes to the pending partial line; returns false on ENOMEM. */
static bool append(char **buf, size_t *len, size_t *cap, const char *s, size_t n)
{
    if (n > *cap - *len) {
        size_t ncap = *cap ? *cap : 4096;
        while (ncap - *len < n) {
            if (ncap > SIZE_MAX / 2)
                return false;
            ncap *= 2;
        }
        char *p = realloc(*buf, ncap);
        if (!p)
            return false;
        *buf = p;
        *cap = ncap;
    }
    memcpy(*buf + *len, s, n);
    *len += n;
    return true;
}

int calc_main(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    static char chunk[1 << 16];
    struct evaluator ev = { 0 };
    char *line = NULL;          /* holds a line split across chunks */
    size_t line_len = 0, line_cap = 0;
    bool ok = true;
    size_t n;

    while (ok && (n = fread(chunk, 1, sizeof chunk, stdin)) > 0) {
        const char *p = chunk, *end = chunk + n;
        const char *nl;

        while (ok && (nl = memchr(p, '\n', (size_t)(end - p))) != NULL) {
            size_t seg = (size_t)(nl - p);
            if (line_len > 0) {
                ok = append(&line, &line_len, &line_cap, p, seg) &&
                     process_line(&ev, line, line_len);
                line_len = 0;
            } else {
                ok = process_line(&ev, p, seg);
            }
            p = nl + 1;
        }
        if (ok && p < end)
            ok = append(&line, &line_len, &line_cap, p, (size_t)(end - p));
    }

    /* A final line without a trailing newline is still an expression. */
    if (ok && line_len > 0)
        ok = process_line(&ev, line, line_len);

    free(line);
    free(ev.vals);
    free(ev.ops);

    if (!ok) {
        fputs("calc: out of memory\n", stderr);
        return EXIT_FAILURE;
    }
    if (ferror(stdin)) {
        perror("calc: read error");
        return EXIT_FAILURE;
    }
    if (fflush(stdout) != 0) {
        perror("calc: write error");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

/*
 * `app lru`: LRU cache simulator (see SPEC.md, section "lru").
 *
 * Design
 * ------
 * All of standard input is read into one buffer up front. Keys and values
 * are never copied: cache entries point straight into that buffer, which
 * lives until the command finishes.
 *
 * Entries live in a fixed pool of `capacity` nodes, addressed by 32-bit
 * indices. Index 0 is reserved as the sentinel of a circular doubly linked
 * recency list (most recently used right after the sentinel, least recently
 * used right before it), and also serves as the "null" link everywhere else.
 * A separately chained hash table maps keys to node indices. Every command
 * is therefore O(1) expected time, and memory is bounded by the capacity.
 */
#include "lru.h"

#include <inttypes.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LRU_MAX_CAPACITY 1000000UL
#define NIL 0u

struct node {
    const char *key;
    const char *val;
    uint32_t klen;
    uint32_t vlen;
    uint32_t hash;
    uint32_t prev;   /* recency list */
    uint32_t next;   /* recency list; free-list link when unused */
    uint32_t chain;  /* next node in the same hash bucket */
};

struct lru {
    struct node *nodes;     /* nodes[0] is the list sentinel */
    uint32_t *buckets;      /* head node index per bucket, NIL if empty */
    uint32_t mask;          /* bucket count - 1 (power of two) */
    uint32_t capacity;
    uint32_t size;
    uint32_t used;          /* nodes ever handed out (bump allocator) */
    uint32_t free_list;     /* recycled nodes, linked through `next` */
};

/* ---------- hashing ---------- */

static uint32_t hash_bytes(const char *s, size_t n)
{
    /* 64-bit FNV-1a with a final avalanche, folded to 32 bits. */
    uint64_t h = 0xcbf29ce484222325ULL;
    for (size_t i = 0; i < n; i++) {
        h ^= (unsigned char)s[i];
        h *= 0x100000001b3ULL;
    }
    h ^= h >> 33;
    h *= 0xff51afd7ed558ccdULL;
    h ^= h >> 33;
    return (uint32_t)h;
}

/* ---------- cache ---------- */

static bool lru_init(struct lru *c, uint32_t capacity)
{
    size_t nbuckets = 1;
    while (nbuckets < capacity)
        nbuckets <<= 1;

    *c = (struct lru){ .capacity = capacity, .mask = (uint32_t)(nbuckets - 1) };
    c->nodes = malloc(((size_t)capacity + 1) * sizeof *c->nodes);
    c->buckets = calloc(nbuckets, sizeof *c->buckets);
    if (c->nodes == NULL || c->buckets == NULL) {
        free(c->nodes);
        free(c->buckets);
        return false;
    }
    c->nodes[NIL].prev = NIL;
    c->nodes[NIL].next = NIL;
    return true;
}

static void lru_free(struct lru *c)
{
    free(c->nodes);
    free(c->buckets);
}

static void list_unlink(struct lru *c, uint32_t i)
{
    struct node *n = &c->nodes[i];
    c->nodes[n->prev].next = n->next;
    c->nodes[n->next].prev = n->prev;
}

static void list_push_front(struct lru *c, uint32_t i)
{
    struct node *n = &c->nodes[i];
    n->prev = NIL;
    n->next = c->nodes[NIL].next;
    c->nodes[n->next].prev = i;
    c->nodes[NIL].next = i;
}

static void touch(struct lru *c, uint32_t i)
{
    if (c->nodes[NIL].next != i) {
        list_unlink(c, i);
        list_push_front(c, i);
    }
}

/*
 * Find `key`. Returns its node index or NIL. If `link` is non-NULL it
 * receives the address of the link that points at the node (or at NIL when
 * absent), so the caller can unlink it from its bucket in O(1).
 */
static uint32_t lookup(struct lru *c, const char *key, uint32_t klen,
                       uint32_t hash, uint32_t **link)
{
    uint32_t *p = &c->buckets[hash & c->mask];
    while (*p != NIL) {
        const struct node *n = &c->nodes[*p];
        if (n->hash == hash && n->klen == klen && memcmp(n->key, key, klen) == 0)
            break;
        p = &c->nodes[*p].chain;
    }
    if (link != NULL)
        *link = p;
    return *p;
}

/* Remove node `i` (whose bucket link is `*link`) and recycle it. */
static void remove_node(struct lru *c, uint32_t i, uint32_t *link)
{
    *link = c->nodes[i].chain;
    list_unlink(c, i);
    c->nodes[i].next = c->free_list;
    c->free_list = i;
    c->size--;
}

static void evict_lru(struct lru *c)
{
    uint32_t victim = c->nodes[NIL].prev;
    struct node *v = &c->nodes[victim];
    uint32_t *link;
    lookup(c, v->key, v->klen, v->hash, &link);
    remove_node(c, victim, link);
}

static uint32_t alloc_node(struct lru *c)
{
    if (c->free_list != NIL) {
        uint32_t i = c->free_list;
        c->free_list = c->nodes[i].next;
        return i;
    }
    return ++c->used;
}

static void lru_set(struct lru *c, const char *key, uint32_t klen,
                    const char *val, uint32_t vlen)
{
    uint32_t hash = hash_bytes(key, klen);
    uint32_t i = lookup(c, key, klen, hash, NULL);

    if (i != NIL) {
        c->nodes[i].val = val;
        c->nodes[i].vlen = vlen;
        touch(c, i);
        return;
    }

    /*
     * Inserting a new key into a full cache would leave C + 1 keys, so the
     * least recently used one goes. Evicting first is equivalent, and keeps
     * the pool at exactly C nodes.
     */
    if (c->size == c->capacity)
        evict_lru(c);

    i = alloc_node(c);
    struct node *n = &c->nodes[i];
    n->key = key;
    n->klen = klen;
    n->val = val;
    n->vlen = vlen;
    n->hash = hash;
    uint32_t *bucket = &c->buckets[hash & c->mask];
    n->chain = *bucket;
    *bucket = i;
    list_push_front(c, i);
    c->size++;
}

static const struct node *lru_get(struct lru *c, const char *key, uint32_t klen)
{
    uint32_t i = lookup(c, key, klen, hash_bytes(key, klen), NULL);
    if (i == NIL)
        return NULL;
    touch(c, i);
    return &c->nodes[i];
}

static bool lru_del(struct lru *c, const char *key, uint32_t klen)
{
    uint32_t *link;
    uint32_t i = lookup(c, key, klen, hash_bytes(key, klen), &link);
    if (i == NIL)
        return false;
    remove_node(c, i, link);
    return true;
}

/* ---------- input ---------- */

/* Read all of `in` into a heap buffer. Returns NULL on failure. */
static char *read_all(FILE *in, size_t *len_out)
{
    size_t cap = 1 << 16;
    size_t len = 0;
    char *buf = malloc(cap);
    if (buf == NULL)
        return NULL;

    for (;;) {
        if (len == cap) {
            char *grown = realloc(buf, cap * 2);
            if (grown == NULL) {
                free(buf);
                return NULL;
            }
            buf = grown;
            cap *= 2;
        }
        size_t got = fread(buf + len, 1, cap - len, in);
        len += got;
        if (got == 0) {
            if (ferror(in)) {
                free(buf);
                return NULL;
            }
            break;
        }
    }
    *len_out = len;
    return buf;
}

struct slice {
    const char *ptr;
    size_t len;
};

/* Pop the next line from `*rest` (without its terminator). */
static bool next_line(struct slice *rest, struct slice *line)
{
    if (rest->len == 0)
        return false;

    const char *nl = memchr(rest->ptr, '\n', rest->len);
    size_t n = nl != NULL ? (size_t)(nl - rest->ptr) : rest->len;

    line->ptr = rest->ptr;
    line->len = n;
    if (n > 0 && line->ptr[n - 1] == '\r')
        line->len--;

    size_t consumed = nl != NULL ? n + 1 : n;
    rest->ptr += consumed;
    rest->len -= consumed;
    return true;
}

/* Pop the next space-separated token from `*line`. */
static struct slice next_token(struct slice *line)
{
    const char *sp = memchr(line->ptr, ' ', line->len);
    size_t n = sp != NULL ? (size_t)(sp - line->ptr) : line->len;
    struct slice tok = { line->ptr, n };
    size_t consumed = sp != NULL ? n + 1 : n;
    line->ptr += consumed;
    line->len -= consumed;
    return tok;
}

static bool slice_eq(struct slice s, const char *lit)
{
    size_t n = strlen(lit);
    return s.len == n && memcmp(s.ptr, lit, n) == 0;
}

/* Parse the capacity line; returns 0 if it is not a valid capacity. */
static uint32_t parse_capacity(struct slice s)
{
    size_t i = 0;
    while (i < s.len && (s.ptr[i] == ' ' || s.ptr[i] == '\t'))
        i++;

    unsigned long value = 0;
    size_t digits = 0;
    for (; i < s.len && s.ptr[i] >= '0' && s.ptr[i] <= '9'; i++, digits++) {
        value = value * 10 + (unsigned long)(s.ptr[i] - '0');
        if (value > LRU_MAX_CAPACITY)
            return 0;
    }

    while (i < s.len && (s.ptr[i] == ' ' || s.ptr[i] == '\t'))
        i++;
    if (digits == 0 || i != s.len)
        return 0;
    return (uint32_t)value;
}

/* ---------- driver ---------- */

static void run(struct lru *c, struct slice rest, FILE *out)
{
    struct slice line;
    while (next_line(&rest, &line)) {
        struct slice cmd = next_token(&line);

        if (slice_eq(cmd, "GET")) {
            struct slice key = next_token(&line);
            const struct node *n = lru_get(c, key.ptr, (uint32_t)key.len);
            if (n != NULL) {
                fwrite(n->val, 1, n->vlen, out);
                putc('\n', out);
            } else {
                fputs("NULL\n", out);
            }
        } else if (slice_eq(cmd, "SET")) {
            struct slice key = next_token(&line);
            struct slice val = next_token(&line);
            lru_set(c, key.ptr, (uint32_t)key.len, val.ptr, (uint32_t)val.len);
        } else if (slice_eq(cmd, "DEL")) {
            struct slice key = next_token(&line);
            fputs(lru_del(c, key.ptr, (uint32_t)key.len) ? "1\n" : "0\n", out);
        } else if (slice_eq(cmd, "SIZE")) {
            fprintf(out, "%" PRIu32 "\n", c->size);
        }
        /* Blank or unrecognised lines are ignored. */
    }
}

int lru_main(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    size_t len;
    char *input = read_all(stdin, &len);
    if (input == NULL) {
        fputs("lru: failed to read standard input\n", stderr);
        return EXIT_FAILURE;
    }

    struct slice rest = { input, len };
    struct slice first;
    if (!next_line(&rest, &first)) {
        free(input);
        return EXIT_SUCCESS; /* empty input: nothing to do */
    }

    uint32_t capacity = parse_capacity(first);
    if (capacity == 0) {
        fputs("lru: invalid capacity\n", stderr);
        free(input);
        return EXIT_FAILURE;
    }

    struct lru cache;
    if (!lru_init(&cache, capacity)) {
        fputs("lru: out of memory\n", stderr);
        free(input);
        return EXIT_FAILURE;
    }

    static char outbuf[1 << 16];
    setvbuf(stdout, outbuf, _IOFBF, sizeof outbuf);

    run(&cache, rest, stdout);

    int status = EXIT_SUCCESS;
    if (fflush(stdout) != 0 || ferror(stdout)) {
        fputs("lru: write error\n", stderr);
        status = EXIT_FAILURE;
    }

    lru_free(&cache);
    free(input);
    return status;
}

/*
 * Entry point: dispatches the first argument to a subcommand.
 *
 * Each subcommand receives argc/argv shifted so that argv[0] is the
 * subcommand name, and its return value becomes the process exit status.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "calc/calc.h"
#include "lru/lru.h"
#include "wordfreq/wordfreq.h"

struct command {
    const char *name;
    int (*run)(int argc, char **argv);
};

static const struct command commands[] = {
    { "wordfreq", wordfreq_main },
    { "lru",      lru_main      },
    { "calc",     calc_main     },
};

static void usage(FILE *out, const char *prog)
{
    fprintf(out, "usage: %s <command>\n\ncommands:\n", prog);
    for (size_t i = 0; i < sizeof commands / sizeof commands[0]; i++)
        fprintf(out, "  %s\n", commands[i].name);
}

int main(int argc, char **argv)
{
    const char *prog = argc > 0 ? argv[0] : "app";

    if (argc < 2) {
        usage(stderr, prog);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < sizeof commands / sizeof commands[0]; i++) {
        if (strcmp(argv[1], commands[i].name) == 0)
            return commands[i].run(argc - 1, argv + 1);
    }

    fprintf(stderr, "%s: unknown command '%s'\n", prog, argv[1]);
    usage(stderr, prog);
    return EXIT_FAILURE;
}

/*
 * `app wordfreq`: print the 10 most frequent words of standard input.
 *
 * A word is a maximal run of ASCII letters, folded to lowercase. Input is
 * streamed in fixed-size chunks; a word straddling a chunk boundary is
 * accumulated in a growable buffer. Distinct words are counted in an
 * open-addressing hash table whose keys live in a single byte arena, and the
 * top entries are then picked with a bounded insertion selection.
 */
#include "wordfreq.h"

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

enum {
    TOP_N = 10,
    READ_CHUNK = 1 << 16,
    INITIAL_SLOTS = 1 << 12,   /* power of two */
    INITIAL_ARENA = 1 << 16,
};

/* ---- growable byte buffer --------------------------------------------- */

struct bytebuf {
    char *data;
    size_t len;
    size_t cap;
};

static bool bytebuf_reserve(struct bytebuf *b, size_t extra)
{
    if (extra <= b->cap - b->len)
        return true;
    if (extra > SIZE_MAX - b->len)
        return false;

    size_t need = b->len + extra;
    size_t cap = b->cap ? b->cap : INITIAL_ARENA;
    while (cap < need)
        cap = cap > SIZE_MAX / 2 ? need : cap * 2;

    char *p = realloc(b->data, cap);
    if (!p)
        return false;
    b->data = p;
    b->cap = cap;
    return true;
}

static bool bytebuf_append(struct bytebuf *b, const char *src, size_t n)
{
    if (!bytebuf_reserve(b, n))
        return false;
    memcpy(b->data + b->len, src, n);
    b->len += n;
    return true;
}

/* ---- word table -------------------------------------------------------- */

struct entry {
    uint64_t hash;
    size_t offset;   /* into the arena */
    size_t len;      /* 0 marks an empty slot: words are never empty */
    uint64_t count;
};

struct table {
    struct entry *slots;
    size_t mask;     /* slot count - 1 */
    size_t used;
    struct bytebuf arena;
};

/* FNV-1a, 64-bit. */
static uint64_t hash_bytes(const char *s, size_t n)
{
    uint64_t h = 0xcbf29ce484222325u;
    for (size_t i = 0; i < n; i++) {
        h ^= (unsigned char)s[i];
        h *= 0x100000001b3u;
    }
    return h;
}

static bool table_init(struct table *t)
{
    t->slots = calloc(INITIAL_SLOTS, sizeof *t->slots);
    if (!t->slots)
        return false;
    t->mask = INITIAL_SLOTS - 1;
    t->used = 0;
    t->arena = (struct bytebuf){ 0 };
    return true;
}

static void table_free(struct table *t)
{
    free(t->slots);
    free(t->arena.data);
}

static bool table_grow(struct table *t)
{
    size_t nslots = (t->mask + 1) * 2;
    if (nslots > SIZE_MAX / sizeof(struct entry))
        return false;

    struct entry *slots = calloc(nslots, sizeof *slots);
    if (!slots)
        return false;

    size_t mask = nslots - 1;
    for (size_t i = 0; i <= t->mask; i++) {
        const struct entry *e = &t->slots[i];
        if (e->len == 0)
            continue;
        size_t j = (size_t)e->hash & mask;
        while (slots[j].len != 0)
            j = (j + 1) & mask;
        slots[j] = *e;
    }

    free(t->slots);
    t->slots = slots;
    t->mask = mask;
    return true;
}

/* Count one occurrence of the lowercase word w[0..n), n > 0. */
static bool table_add(struct table *t, const char *w, size_t n)
{
    uint64_t h = hash_bytes(w, n);
    size_t i = (size_t)h & t->mask;

    for (;;) {
        struct entry *e = &t->slots[i];
        if (e->len == 0)
            break;
        if (e->hash == h && e->len == n &&
            memcmp(t->arena.data + e->offset, w, n) == 0) {
            e->count++;
            return true;
        }
        i = (i + 1) & t->mask;
    }

    size_t offset = t->arena.len;
    if (!bytebuf_append(&t->arena, w, n))
        return false;
    t->slots[i] = (struct entry){ .hash = h, .offset = offset, .len = n, .count = 1 };
    t->used++;

    /* Keep the load factor at or below 1/2. */
    if (t->used * 2 > t->mask + 1)
        return table_grow(t);
    return true;
}

/* ---- tokenizer --------------------------------------------------------- */

/* Maps a byte to its lowercase letter, or 0 if it is not an ASCII letter. */
static unsigned char letter_of[256];

static void init_letters(void)
{
    for (int c = 'a'; c <= 'z'; c++) {
        letter_of[c] = (unsigned char)c;
        letter_of[c - 'a' + 'A'] = (unsigned char)c;
    }
}

/*
 * Lowercase and count every word in buf[0..n). A word cut off at the end of
 * the chunk is moved to `pending`; one carried in from the previous chunk is
 * completed with the leading letters of this one.
 */
static bool scan_chunk(struct table *t, struct bytebuf *pending, char *buf, size_t n)
{
    size_t i = 0;

    while (i < n) {
        if (!letter_of[(unsigned char)buf[i]]) {
            /* A separator completes any word carried from the last chunk. */
            if (pending->len > 0) {
                if (!table_add(t, pending->data, pending->len))
                    return false;
                pending->len = 0;
            }
            i++;
            continue;
        }

        size_t start = i;
        do {
            buf[i] = (char)letter_of[(unsigned char)buf[i]];
            i++;
        } while (i < n && letter_of[(unsigned char)buf[i]]);

        if (i == n)   /* may continue in the next chunk */
            return bytebuf_append(pending, buf + start, i - start);

        if (pending->len > 0) {
            if (!bytebuf_append(pending, buf + start, i - start) ||
                !table_add(t, pending->data, pending->len))
                return false;
            pending->len = 0;
        } else if (!table_add(t, buf + start, i - start)) {
            return false;
        }
    }

    return true;
}

/* ---- ranking ----------------------------------------------------------- */

static int compare_words(const struct table *t, const struct entry *a, const struct entry *b)
{
    size_t n = a->len < b->len ? a->len : b->len;
    int c = memcmp(t->arena.data + a->offset, t->arena.data + b->offset, n);
    if (c != 0)
        return c;
    return (a->len > b->len) - (a->len < b->len);
}

/* True if a ranks strictly before b: higher count, then smaller word. */
static bool ranks_before(const struct table *t, const struct entry *a, const struct entry *b)
{
    if (a->count != b->count)
        return a->count > b->count;
    return compare_words(t, a, b) < 0;
}

/* Fill top[] with the best entries in rank order; returns how many. */
static size_t select_top(const struct table *t, const struct entry *top[TOP_N])
{
    size_t k = 0;

    for (size_t i = 0; i <= t->mask; i++) {
        const struct entry *e = &t->slots[i];
        if (e->len == 0)
            continue;
        if (k == TOP_N && !ranks_before(t, e, top[k - 1]))
            continue;

        size_t j = k < TOP_N ? k++ : TOP_N - 1;
        while (j > 0 && ranks_before(t, e, top[j - 1])) {
            top[j] = top[j - 1];
            j--;
        }
        top[j] = e;
    }
    return k;
}

/* ---- entry point ------------------------------------------------------- */

int wordfreq_main(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    int status = EXIT_FAILURE;
    struct table table;
    struct bytebuf pending = { 0 };
    char *chunk = malloc(READ_CHUNK);

    if (!chunk || !table_init(&table)) {
        free(chunk);
        fputs("wordfreq: out of memory\n", stderr);
        return EXIT_FAILURE;
    }
    init_letters();

    size_t n;
    while ((n = fread(chunk, 1, READ_CHUNK, stdin)) > 0) {
        if (!scan_chunk(&table, &pending, chunk, n)) {
            fputs("wordfreq: out of memory\n", stderr);
            goto out;
        }
    }
    if (ferror(stdin)) {
        perror("wordfreq: read error");
        goto out;
    }
    if (pending.len > 0 && !table_add(&table, pending.data, pending.len)) {
        fputs("wordfreq: out of memory\n", stderr);
        goto out;
    }

    const struct entry *top[TOP_N];
    size_t k = select_top(&table, top);
    for (size_t i = 0; i < k; i++) {
        printf("%llu ", (unsigned long long)top[i]->count);
        fwrite(table.arena.data + top[i]->offset, 1, top[i]->len, stdout);
        putchar('\n');
    }
    if (fflush(stdout) != 0) {
        perror("wordfreq: write error");
        goto out;
    }
    status = EXIT_SUCCESS;

out:
    free(pending.data);
    free(chunk);
    table_free(&table);
    return status;
}
